    v_alpha = i_alpha;
    v_borderWidth = i_borderWidth;
    v_ballStyle = u_ballStyle;
    v_textureType = u_textureType;
    v_textureOpacity = u_textureOpacity;
    v_glowAmount = u_glowAmount;
    
