    var finalAlpha = max(ballAlpha, glowAlpha);
    if (style == 4) { // GHOST
        finalAlpha = finalAlpha * 0.5;
    }
    if (style == 11) { // FROSTED
        finalAlpha = finalAlpha * 0.8;
    }
    if (style == 8) { // WIREFRAME
        var grid = 0.0;
        if (fract(in.localPos.x * 10.0) > 0.9 || fract(in.localPos.y * 10.0) > 0.9 || dist > 0.98) {
            grid = 1.0;
        }
        finalAlpha = finalAlpha * grid;
    }

    if (finalAlpha < 0.001) { discard; }
